function estado(resto) {
  if (resto < 0) {
    return "vencido";
  }
  if (resto <= 5) {
    return "urgente";
  }
  return "en plazo";
}
test("normal", () => {
  expect(estado(20)).toBe("en plazo");
});
test("límite", () => {
  expect(estado(0)).toBe("urgente");
});
test("vencido", () => {
  expect(estado(-1)).toBe("vencido");
});

const limites = {
  brecha: 72,
  acceso: 30,
};
function quedan(tipo, pasado) {
  return limites[tipo] - pasado;
}
function estado(resto) {
  if (resto < 0) {
    return "vencido";
  }
  if (resto <= 5) {
    return "urgente";
  }
  return "en plazo";
}
test("tipo raro", () => {
  const r = quedan("queja", 5);
  const e = estado(r);
  expect(e).toBe("desconocido");
});

